oxy_webhelp_navlinks = {"migration_arch_loc_rcv-d39307e9770":{"topics":[{"title":"Archival location migration planning","shortdesc":"<p class=\"shortdesc\">Planning the migration scope, SLA Domain configurations, tool selection, and         sequencing before migrating archival data minimizes disruption and ensures a smooth         transition. Effective planning reduces the risk of errors, lowers storage costs from running         parallel systems, and ensures that the migration preserves data integrity and meets         retention requirements.<\/p>","href":"archival\/arch_loc_migration_planning.html","attributes":{"data-id":"arch_loc_migration_planning"},"menu":{"hasChildren":false},"tocID":"arch_loc_migration_planning-d39307e9781","topics":[]},{"title":"Prerequisites for archival location migration","shortdesc":"<p class=\"shortdesc\">Before migrating an archival location, ensure that your source location, Rubrik         cluster, and SLA Domain configurations meet all the requirements for the selected migration         type.<\/p>","href":"archival\/arch_loc_migration_prereq.html","attributes":{"data-id":"arch_loc_migration_prereq"},"menu":{"hasChildren":false},"tocID":"arch_loc_migration_prereq-d39307e9792","topics":[]},{"title":"Prerequisites for migrating archival locations to RCV","shortdesc":"<p class=\"shortdesc\">Before migrating your data center archival location to Rubrik Cloud Vault, ensure         your source location, Rubrik cluster, and SLA Domain configurations meet all         requirements.<\/p>","href":"saas\/rcv_prereq_arch_loc_migration.html","attributes":{"data-id":"rcv_prereq_arch_loc_migration"},"menu":{"hasChildren":false},"tocID":"rcv_prereq_arch_loc_migration-d39307e9803","topics":[]},{"title":"Rubrik data mover and AWS DataSync agent requirements","shortdesc":"<p class=\"shortdesc\">Information about the compute, network, and firewall requirements for deploying the         Rubrik data mover and the AWS DataSync agent in your environment.<\/p>","href":"archival\/arch_loc_agent_reqs.html","attributes":{"data-id":"arch_loc_agent_reqs"},"menu":{"hasChildren":false},"tocID":"arch_loc_agent_reqs-d39307e9814","topics":[]},{"title":"Creating a service account for Rubrik data mover credential issuance","shortdesc":"<p class=\"shortdesc\">Create an <span class=\"ph\">RSC<\/span> service account with the Generate data mover         credentials permission so that the Rubrik data mover can obtain short-lived AWS credentials         during the migration.<\/p>","href":"archival\/rcv_data_mover_rbac_setup.html","attributes":{"data-id":"rcv_data_mover_rbac_setup"},"menu":{"hasChildren":false},"tocID":"rcv_data_mover_rbac_setup-d39307e9825","topics":[]},{"title":"RCV migration workflow","shortdesc":"<p class=\"shortdesc\">Migration of archival locations to Rubrik Cloud Vault involves specific         responsibilities for both the customer and Rubrik Professional Services, depending on         whether the workflow is customer-hosted or Rubrik-hosted.<\/p>","href":"saas\/rcv_migration_workflow.html","attributes":{"data-id":"rcv_migration_workflow"},"menu":{"hasChildren":false},"tocID":"rcv_migration_workflow-d39307e9839","topics":[]},{"title":"Customer-hosted migration process","shortdesc":"<p class=\"shortdesc\">You can migrate an archival location to RCV by running the migration tool in your own         AWS environment.<\/p>","href":"saas\/rcv_cust_managed_migration_process.html","attributes":{"data-id":"rcv_cust_managed_migration_process"},"menu":{"hasChildren":false},"tocID":"rcv_cust_managed_migration_process-d39307e9850","next":"rcv_cust_managed_migration_process-d39307e9850"},{"title":"Rubrik-hosted migration process","shortdesc":"<p class=\"shortdesc\">You can migrate an archival location to RCV by authorizing Rubrik to run the         migration tool within the Rubrik AWS environment.<\/p>","href":"saas\/rcv_rbk_managed_migration_process.html","attributes":{"data-id":"rcv_rbk_managed_migration_process"},"menu":{"hasChildren":false},"tocID":"rcv_rbk_managed_migration_process-d39307e9908","next":"rcv_rbk_managed_migration_process-d39307e9908"},{"title":"Updating SLA Domains after migrating to RCV Archive tier","shortdesc":"<p class=\"shortdesc\">After migrating an S3-compatible archival location to an RCV Archive tier location,         you must update the associated SLA Domains to enable instant tiering to Glacier Deep Archive         before re-enabling the location.<\/p>","href":"archival\/arch_loc_update_sla_archive_tier_migration.html","attributes":{"data-id":"arch_loc_update_sla_archive_tier_migration"},"menu":{"hasChildren":false},"tocID":"arch_loc_update_sla_archive_tier_migration-d39307e9963","topics":[]}]}};